-- Schema documentation metadata. Keep changes beside schema changes.
CREATE TABLE IF NOT EXISTS schema_metadata (
  object_kind TEXT NOT NULL CHECK (object_kind IN ('group','table','column','logical_ref')),
  schema_name TEXT NOT NULL DEFAULT 'public',
  object_name TEXT NOT NULL,
  meta_version INTEGER NOT NULL DEFAULT 1 CHECK (meta_version = 1),
  details JSONB NOT NULL,
  PRIMARY KEY (object_kind, schema_name, object_name)
);
COMMENT ON TABLE schema_metadata IS 'Versioned business descriptions and logical references used to generate the ER documentation.';
INSERT INTO schema_metadata (object_kind,schema_name,object_name,details) VALUES ('group','public','Billing handoff and settlement','{"purpose":"Balance snapshots, confirmations, authorization, and final decisions during ownership handoff.","scenario":"Used to freeze responsibility, confirm financial evidence, and commit or finalize an owner transfer.","service":"Billing"}'::jsonb) ON CONFLICT (object_kind,schema_name,object_name) DO UPDATE SET details=EXCLUDED.details;
